create table if not exists public.crm_predictive_evaluations (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), conversation_id uuid not null references public.crm_conversations(id) on delete cascade, model_version text not null, predicted_conversion numeric(6,5) not null check (predicted_conversion between 0 and 1), predicted_recovery numeric(6,5) not null check (predicted_recovery between 0 and 1), predicted_ltv numeric(6,5) not null check (predicted_ltv between 0 and 1), actual_conversion boolean, actual_recovery boolean, actual_ltv numeric, evaluated_at timestamptz, created_at timestamptz not null default now());
create index if not exists crm_predictive_evaluations_user_version_created_idx on public.crm_predictive_evaluations(user_id, model_version, created_at desc);
create index if not exists crm_predictive_evaluations_conversation_idx on public.crm_predictive_evaluations(conversation_id, created_at desc);
alter table public.crm_predictive_evaluations enable row level security;
drop policy if exists crm_predictive_evaluations_owner on public.crm_predictive_evaluations;
create policy crm_predictive_evaluations_owner on public.crm_predictive_evaluations for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create or replace function public.crm_predictive_evaluation_summary(p_model_version text default 'deterministic_behavioral_v1') returns jsonb language sql stable security invoker set search_path=public as $$ with s as (select * from public.crm_predictive_evaluations where user_id=auth.uid() and model_version=p_model_version), c as (select count(*) filter (where actual_conversion is not null) n_conversion, count(*) filter (where actual_recovery is not null) n_recovery, avg(abs(predicted_conversion-(case when actual_conversion then 1 else 0 end))) filter (where actual_conversion is not null) mae_conversion, avg(abs(predicted_recovery-(case when actual_recovery then 1 else 0 end))) filter (where actual_recovery is not null) mae_recovery from s) select jsonb_build_object('model_version',p_model_version,'evaluated_examples',greatest(n_conversion,n_recovery),'conversion_mae',mae_conversion,'recovery_mae',mae_recovery,'evaluation_type','post_outcome_calibration','generated_at',now()) from c $$;
revoke all on public.crm_predictive_evaluations from anon;
grant select,insert,update,delete on public.crm_predictive_evaluations to authenticated;
revoke all on function public.crm_predictive_evaluation_summary(text) from anon;
grant execute on function public.crm_predictive_evaluation_summary(text) to authenticated;
